using System;using System.Collections.Generic;using System.Linq;
namespace RoadRush.TerrainDraft {
 public readonly struct LocalHeightPacket {public readonly double OriginY;public readonly float[] LocalY;public readonly double MaximumEmissionError;public LocalHeightPacket(double origin,float[] y,double error){OriginY=origin;LocalY=y;MaximumEmissionError=error;}}
 public static class DoubleTerrainEmission {
  public const string Recipe="DoubleField-IntegerYOrigin-CommonSeamFloat1";
  public static double ChooseOrigin(IReadOnlyList<double> worldHeights){if(worldHeights==null||worldHeights.Count==0||worldHeights.Count>120000)throw new ArgumentException("Height inputcap");double low=double.PositiveInfinity,high=double.NegativeInfinity;foreach(double y in worldHeights){if(!TerrainFieldLimits.Finite(y)||Math.Abs(y)>100000)throw new ArgumentException("Height source budget");low=Math.Min(low,y);high=Math.Max(high,y);}return Math.Round(low+(high-low)*.5,MidpointRounding.ToEven);}
  static double Quantum(double local){if(local==0)return Math.Pow(2,-149);int exponent=(int)Math.Floor(Math.Log(Math.Abs(local),2));return Math.Pow(2,Math.Max(-149,exponent-23));}
  // Canonical shared border height is chosen ONCE for every incident owner.
  // Re-evaluating field/rounding separately per owner is forbidden.
  public static double SharedHeight(double rawWorldY,IReadOnlyList<double> ownerOrigins,double maximumError=.000002){if(!TerrainFieldLimits.Finite(rawWorldY)||Math.Abs(rawWorldY)>100000||!TerrainFieldLimits.Finite(maximumError)||maximumError>.0002||ownerOrigins==null||ownerOrigins.Count<1||ownerOrigins.Count>4||maximumError<=0)throw new ArgumentException("Sharedheight inputs");double step=0;foreach(double origin in ownerOrigins){if(!TerrainFieldLimits.Finite(origin)||origin!=Math.Round(origin)||Math.Abs(origin)>100000)throw new ArgumentException("Canonical integer origin required");step=Math.Max(step,Quantum(rawWorldY-origin));}for(int pass=0;pass<3;pass++){double target=Math.Round(rawWorldY/step,MidpointRounding.ToEven)*step;if(Math.Abs(target-rawWorldY)>maximumError)throw new ArgumentException("Sharedheight emission exceeds explicit bound");bool valid=true;foreach(double origin in ownerOrigins)if(origin+(double)(float)(target-origin)!=target){valid=false;break;}if(valid)return target;step*=2;}throw new ArgumentException("No common representable seamheight within bounded iterations");}
  public static LocalHeightPacket Emit(double originY,IReadOnlyList<double> finalWorldHeights,IReadOnlyDictionary<int,double> canonicalSharedWorldY=null,double maximumError=.000002){if(!TerrainFieldLimits.Finite(originY)||Math.Abs(originY)>100000||!TerrainFieldLimits.Finite(maximumError)||maximumError<=0||maximumError>.0002||originY!=Math.Round(originY)||finalWorldHeights==null||finalWorldHeights.Count>120000)throw new ArgumentException("Localheight inputcap");var output=new float[finalWorldHeights.Count];double maximum=0;for(int i=0;i<output.Length;i++){double raw=finalWorldHeights[i];if(!TerrainFieldLimits.Finite(raw)||Math.Abs(raw)>100000)throw new ArgumentException("Localheight finite/bounds");double y=canonicalSharedWorldY!=null&&canonicalSharedWorldY.TryGetValue(i,out double shared)?shared:raw;float local=(float)(y-originY);if(canonicalSharedWorldY!=null&&canonicalSharedWorldY.ContainsKey(i)&&originY+(double)local!=y)throw new ArgumentException("Canonical border height not representable by owner");double error=Math.Abs(originY+(double)local-raw);if(error>maximumError)throw new ArgumentException("Final localheight exceeds explicit error bound");maximum=Math.Max(maximum,error);output[i]=local;}return new LocalHeightPacket(originY,output,maximum);}
 }
}
